    // ===== MODEL =====
    public class StudentAttView
    {
        public string MaHsSo { get; set; } = "";
        public string MaLop { get; set; } = "";
        public string TenLop { get; set; } = "";
        public string HoTen { get; set; } = "";
        public string NgaySinh { get; set; } = "";

        public string TrangThaiSang { get; set; } = "";
        public string TrangThaiChieu { get; set; } = "";

        public DateTime? ThoiGianVaoSang { get; set; }
        public DateTime? ThoiGianRaSang { get; set; }
        public DateTime? ThoiGianVaoChieu { get; set; }
        public DateTime? ThoiGianRaChieu { get; set; }
    }

    // ===== STATE =====
    private string? maTruongBo;
    private string? selectedNamHoc;
    private string? selectedCapHoc;
    private string tenTruong = "";

    private List<LopHoc_DTO> DanhSachLop = new();
    private List<StudentAttView> AllStudents = new();
    private List<StudentAttView> FilteredStudents = new();

    // Giữ toàn bộ raw DTO để truyền vào hàm xuất Excel
    private List<DiemDanhHocSinh_DTO> _rawData = new();

    private DateTime SelectedDate { get; set; } = DateTime.Today;
    private string SelectedClass { get; set; } = "";
    private string SelectedStatus { get; set; } = "";
    private string SearchTerm { get; set; } = "";

    private bool _showExportMenu = false;
    private bool isLoading = false;
    private bool isExporting = false;

    // Toast
    private string _toastMessage = "";
    private string _toastCssClass = "";
    private string _toastIcon = "";
    private System.Threading.CancellationTokenSource? _toastCts;

    private int CurrentPage = 1;
    private int PageSize = 15;

    // ===== LIFECYCLE =====
    protected override async Task OnInitializedAsync()
    {
        try
        {
            maTruongBo = await BrowserStorageService.GetMaTruongBoAsync(JSRuntime);
            selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
            selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");
            tenTruong = await BrowserStorageService.GetItem(JS, "tenTruong") ?? "";

            await LoadDanhSachLop();
            await LoadData();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"OnInitializedAsync error: {ex.Message}");
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Đăng ký hàm JS để trigger download file từ byte array
            await JS.InvokeVoidAsync("eval", @"
                if (!window._fileDownloadRegistered) {
                    window.downloadFileFromBytes = function(filename, contentType, bytes) {
                        const blob = new Blob([new Uint8Array(bytes)], { type: contentType });
                        const url  = URL.createObjectURL(blob);
                        const a    = document.createElement('a');
                        a.href     = url;
                        a.download = filename;
                        document.body.appendChild(a);
                        a.click();
                        document.body.removeChild(a);
                        URL.revokeObjectURL(url);
                    };
                    window._fileDownloadRegistered = true;
                }
            ");
        }
    }

    // ===== LOAD LỚP =====
    private async Task LoadDanhSachLop()
    {
        if (string.IsNullOrEmpty(maTruongBo) || string.IsNullOrEmpty(selectedNamHoc)) return;
        try
        {
            DanhSachLop = await TruongService.hGetDanhSachLop(maTruongBo, selectedCapHoc, selectedNamHoc);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi tải lớp: {ex.Message}");
        }
    }

    // ===== LOAD DATA =====
    private async Task LoadData()
    {
        if (string.IsNullOrEmpty(maTruongBo) || string.IsNullOrEmpty(selectedNamHoc))
        {
            AllStudents = new(); FilteredStudents = new(); _rawData = new();
            return;
        }

        isLoading = true;
        StateHasChanged();

        try
        {
            _rawData = await DiemDanhServices.hGetDiemDanhHocSinh(
                SelectedDate,
                selectedNamHoc,
                string.IsNullOrEmpty(SelectedClass) ? null : SelectedClass);

            AllStudents = _rawData.Select(d => new StudentAttView
                {
                    MaHsSo = d.MaHsSo ?? "",
                    MaLop = d.MaLop ?? "",
                    TenLop = d.TenLop ?? "",
                    HoTen = d.HoTen ?? "",
                    NgaySinh = d.NgaySinh ?? "",

                    TrangThaiSang = ResolveTrangThaiSang(d.IsTrangThaiDiemDanhSang, d.IsDonXinPhep),
                    TrangThaiChieu = ResolveTrangThaiChieu(d.IsTrangThaiDiemDanhChieu, d.IsDonXinPhep),

                    ThoiGianVaoSang = d.ThoiGianVaoSang,
                    ThoiGianRaSang = d.ThoiGianRaSang,
                    ThoiGianVaoChieu = d.ThoiGianVaoChieu,
                    ThoiGianRaChieu = d.ThoiGianRaChieu,
                }).ToList();

            FilterData();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi tải điểm danh học sinh: {ex.Message}");
            AllStudents = new(); FilteredStudents = new(); _rawData = new();
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }

    // ===== XUẤT EXCEL THEO NGÀY =====
    private async Task ExportHocSinhNgay(string option)
    {
        _showExportMenu = false;

        if (_rawData == null || _rawData.Count == 0)
        {
            await ShowToast("Không có dữ liệu để xuất!", "toast-warning", "warning");
            return;
        }

        isExporting = true;
        StateHasChanged();

        try
        {
            byte[] bytes = await DiemDanhServices.ExportExcelHocSinhTheoNgay(
                _rawData,
                SelectedDate,
                option,
                tenTruong);

            string optionSuffix = option switch
            {
                "CoMat" => "CoMat",
                "VangMat" => "VangMat",
                _ => "TongQuan"
            };

            string fileName = $"DiemDanh_HocSinh_{optionSuffix}_{SelectedDate:yyyyMMdd}.xlsx";
            string mime = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

            await JS.InvokeVoidAsync("downloadFileFromBytes", fileName, mime, bytes);
            await ShowToast($"Xuất Excel thành công! ({fileName})", "toast-success", "check_circle");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi xuất Excel học sinh: {ex.Message}");
            await ShowToast("Xuất Excel thất bại. Vui lòng thử lại!", "toast-error", "error");
        }
        finally
        {
            isExporting = false;
            StateHasChanged();
        }
    }

    // ===== LƯU THAY ĐỔI (placeholder) =====
    private async Task SaveChanges()
    {
        _showExportMenu = false;
        await ShowToast("Chức năng lưu thay đổi đang được phát triển.", "toast-warning", "info");
    }

    // ===== RESOLVE TRẠNG THÁI =====
    private string ResolveTrangThaiSang(int trangThai, int donPhep)
    {
        if (donPhep == 1 || donPhep == 3) return "Có đơn nghỉ";
        return trangThai switch
        {
            1 => "Có mặt",
            2 => "Điểm danh trễ",
            _ => "Chưa điểm danh"
        };
    }

    private string ResolveTrangThaiChieu(int trangThai, int donPhep)
    {
        if (donPhep == 2 || donPhep == 3) return "Có đơn nghỉ";
        return trangThai switch
        {
            1 => "Có mặt",
            2 => "Điểm danh trễ",
            _ => "Chưa điểm danh"
        };
    }

    // ===== FILTER =====
    private void FilterData()
    {
        FilteredStudents = AllStudents.Where(s =>
            (string.IsNullOrEmpty(SearchTerm) ||
             s.HoTen.Contains(SearchTerm, StringComparison.OrdinalIgnoreCase) ||
             s.MaHsSo.Contains(SearchTerm, StringComparison.OrdinalIgnoreCase)) &&
            (string.IsNullOrEmpty(SelectedClass) || s.MaLop == SelectedClass) &&
            (string.IsNullOrEmpty(SelectedStatus) ||
             s.TrangThaiSang == SelectedStatus ||
             s.TrangThaiChieu == SelectedStatus)
        ).ToList();

        CurrentPage = 1;
    }

    // ===== EVENTS =====
    private async Task OnDateChange() => await LoadData();
    private async Task OnClassChange() => await LoadData();

    // ===== PAGINATION =====
    private List<StudentAttView> PaginatedStudents =>
        FilteredStudents.Skip((CurrentPage - 1) * PageSize).Take(PageSize).ToList();

    private int TotalPages =>
        FilteredStudents.Count == 0 ? 1 : (int)Math.Ceiling((double)FilteredStudents.Count / PageSize);

    private void ChangePage(int p)
    {
        if (p >= 1 && p <= TotalPages) CurrentPage = p;
    }

    private List<int> GetPageNumbers()
    {
        var pages = new List<int>();
        if (TotalPages <= 7)
        {
            for (int i = 1; i <= TotalPages; i++) pages.Add(i);
        }
        else
        {
            pages.Add(1);
            if (CurrentPage > 3) pages.Add(-1);
            for (int i = Math.Max(2, CurrentPage - 1); i <= Math.Min(TotalPages - 1, CurrentPage + 1); i++)
                pages.Add(i);
            if (CurrentPage < TotalPages - 2) pages.Add(-1);
            pages.Add(TotalPages);
        }
        return pages;
    }

    // ===== TOAST =====
    private async Task ShowToast(string message, string cssClass, string icon)
    {
        _toastCts?.Cancel();
        _toastCts = new System.Threading.CancellationTokenSource();

        _toastMessage = message;
        _toastCssClass = cssClass;
        _toastIcon = icon;
        StateHasChanged();

        try
        {
            await Task.Delay(3500, _toastCts.Token);
            _toastMessage = "";
            StateHasChanged();
        }
        catch (TaskCanceledException) { /* bị hủy bởi toast mới */ }
    }

    // ===== HELPERS =====
    private void ToggleExportMenu() => _showExportMenu = !_showExportMenu;

    private string FormatNgaySinh(string ngaySinh)
    {
        if (string.IsNullOrEmpty(ngaySinh)) return "—";
        if (DateTime.TryParse(ngaySinh, out var dt))
            return dt.ToString("dd/MM/yyyy");
        return ngaySinh;
    }

    private string GetStatusClass(string s) => s switch
    {
        "Có mặt" => "status-present",
        "Điểm danh trễ" => "status-late",
        "Có đơn nghỉ" => "status-permit",
        _ => "status-absent"
    };

